const wh = $('Webhook').first().json;
const body = wh.body || {};
const langRaw = String(body.lang || 'kk').toLowerCase();
const lang = langRaw.startsWith('ru') ? 'ru' : 'kk';
const userMessage = String(body.message || wh.query?.message || '').trim() || (lang === 'kk' ? 'Сәлеметсіз бе!' : 'Здравствуйте!');

const doctorsRes = $('GET /api/doctors').first().json;
const servicesRes = $('GET /api/services').first().json;

const doctors = Array.isArray(doctorsRes?.data) ? doctorsRes.data : [];
const services = Array.isArray(servicesRes?.data) ? servicesRes.data : [];

const clinicContext = JSON.stringify({ doctors, services });

const systemKk = 'Сіз DentLux (DentReserve Pro) премиум стоматологиялық клиниканың виртуалды кеңесшісісіз. Барлық жауапты ӘДЕБИ ҚАЗАҚ ТІЛІНДЕ жазыңыз. Деңгей: әлемдегі топ клиникалар — жылы, сыпайы, нақты; JSON контекстіндегі фактілерден ғана; диагноз жоқ; қатты ауырсынуда 103; HTML <b>/<i>; жазылу ұсыныңыз.';
const systemRu = 'Вы консультант DentLux (DentReserve Pro) уровня премиальных клиник. Ответы строго на русском. Только факты из JSON; без диагнозов; при острой боли — скорая; HTML <b>/<i>; предложите запись.';
const system = lang === 'kk' ? systemKk : systemRu;
const tail = lang === 'kk' ? 'Жауапты тек қазақ тілінде, премиум клиника стилінде беріңіз.' : 'Ответ строго на русском, премиальный стиль.';
const prompt = `${system}\n\nКонтекст (JSON): ${clinicContext}\n\nХабарлама: ${userMessage}\n\n${tail}`;

return [{
  json: {
    userMessage,
    lang,
    geminiPayload: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: { maxOutputTokens: 1536, temperature: 0.38 }
    }
  }
}];

const r = $input.first().json;
let text = '';
try {
  text = String(r?.candidates?.[0]?.content?.parts?.[0]?.text || '').trim();
} catch (e) {}
if (!text && r?.error) {
  text = 'Қызмет уақытша қолжетімсіз. Клиникамен хабарласыңыз. Техн.: ' + (typeof r.error === 'string' ? r.error : JSON.stringify(r.error)).slice(0, 900);
}
if (!text) {
  text = JSON.stringify(r).slice(0, 2000);
}
return [{ json: { reply: text } }];
